#[serde(untagged)]
pub enum Cards {
    Ironclad(IroncladCard),
    Silent(SilentCard),
    Regent(RegentCard),
    Necrobinder(NecrobinderCard),
    Defect(DefectCard),
    Colorless(ColorlessCard),
    Curse(CurseCard),
    Event(EventCard),
    Quest(QuestCard),
    Status(StatusCard),
    Token(TokenCard),
    Deprecated(DeprecatedCard),
}

